* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.app {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.game-container {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 20px;
  padding: 40px;
  max-width: 500px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
  border: 1px solid rgba(255, 255, 255, 0.18);
}

h1 {
  font-size: 3rem;
  font-weight: 900;
  margin-bottom: 10px;
  background: linear-gradient(45deg, #ffd700, #ffed4e);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
}

h2 {
  font-size: 1.2rem;
  margin-bottom: 30px;
  opacity: 0.9;
  font-weight: 500;
}

.current-price {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 15px;
  padding: 20px;
  margin-bottom: 30px;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.price-label {
  font-size: 0.9rem;
  opacity: 0.8;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.price-value {
  font-size: 2.5rem;
  font-weight: 700;
  color: #ffd700;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 15px;
  margin-bottom: 30px;
}

.stat {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 15px 10px;
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.stat-number {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 5px;
  color: #ffd700;
}

.stat-label {
  font-size: 0.8rem;
  opacity: 0.8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.game-area {
  margin-top: 20px;
}

.prediction-question {
  font-size: 1.3rem;
  margin-bottom: 25px;
  font-weight: 500;
}

.prediction-buttons {
  display: flex;
  gap: 20px;
  justify-content: center;
}

.prediction-btn {
  font-size: 1.5rem;
  font-weight: 700;
  padding: 20px 40px;
  border: none;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
  min-width: 120px;
}

.up-btn {
  background: linear-gradient(135deg, #00c851, #00a043);
  color: white;
  box-shadow: 0 4px 15px rgba(0, 200, 81, 0.4);
}

.up-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 200, 81, 0.5);
}

.down-btn {
  background: linear-gradient(135deg, #ff4444, #cc0000);
  color: white;
  box-shadow: 0 4px 15px rgba(255, 68, 68, 0.4);
}

.down-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255, 68, 68, 0.5);
}

.prediction-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.game-active {
  text-align: center;
}

.prediction-display {
  font-size: 1.3rem;
  margin-bottom: 15px;
}

.prediction.up {
  color: #00c851;
  font-weight: 700;
}

.prediction.down {
  color: #ff4444;
  font-weight: 700;
}

.start-price {
  font-size: 1.1rem;
  margin-bottom: 20px;
  opacity: 0.9;
}

.countdown {
  margin: 30px 0;
}

.countdown-number {
  font-size: 4rem;
  font-weight: 900;
  color: #ffd700;
  text-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
  margin-bottom: 10px;
}

.countdown-label {
  font-size: 1rem;
  opacity: 0.8;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.live-price {
  font-size: 1.5rem;
  font-weight: 600;
  margin-top: 20px;
  color: #ffd700;
}

.result {
  text-align: center;
}

.result-banner {
  font-size: 2rem;
  font-weight: 900;
  margin-bottom: 25px;
  padding: 20px;
  border-radius: 15px;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.result-banner.win {
  background: linear-gradient(135deg, #00c851, #00a043);
  box-shadow: 0 4px 20px rgba(0, 200, 81, 0.4);
}

.result-banner.lose {
  background: linear-gradient(135deg, #ff4444, #cc0000);
  box-shadow: 0 4px 20px rgba(255, 68, 68, 0.4);
}

.price-comparison {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-bottom: 20px;
}

.price-item {
  background: rgba(255, 255, 255, 0.1);
  padding: 15px 20px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.price-item .price-label {
  font-size: 0.8rem;
  opacity: 0.8;
  margin-bottom: 5px;
  text-transform: uppercase;
}

.price-item .price-value {
  font-size: 1.3rem;
  font-weight: 700;
  color: #ffd700;
}

.arrow {
  font-size: 2rem;
  opacity: 0.7;
}

.price-change {
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 20px;
  padding: 10px 20px;
  border-radius: 10px;
}

.price-change.positive {
  color: #00c851;
  background: rgba(0, 200, 81, 0.1);
  border: 1px solid rgba(0, 200, 81, 0.3);
}

.price-change.negative {
  color: #ff4444;
  background: rgba(255, 68, 68, 0.1);
  border: 1px solid rgba(255, 68, 68, 0.3);
}

.your-prediction {
  font-size: 1.1rem;
  margin-bottom: 25px;
  opacity: 0.9;
}

.play-again-btn {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  font-size: 1.2rem;
  font-weight: 700;
  padding: 15px 30px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.4);
}

