{"path": "src/App.jsx", "content": "import { useState, useEffect, useRef } from 'react'
import './App.css'

// Helper function to call Pyth MCP Server
async function pythMCP(toolName, args) {
  try {
    // Step 1: Initialize session
    const init = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 0, method: 'initialize',
        params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'lololol-game', version: '1.0' } }
      })
    });
    await init.json();

    // Step 2: Call the tool
    const res = await fetch('https://mcp.pyth.network/mcp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0', id: 1, method: 'tools/call',
        params: { name: toolName, arguments: args }
      })
    });
    const data = await res.json();
    const text = data.result?.content?.[0]?.text || '';
    return JSON.parse(text);
  } catch (error) {
    console.error('Pyth MCP error:', error);
    return null;
  }
}

function App() {
  const [currentPrice, setCurrentPrice] = useState(null)
  const [gameState, setGameState] = useState('waiting') // 'waiting', 'active', 'finished'
  const [prediction, setPrediction] = useState(null) // 'up' or 'down'
  const [startPrice, setStartPrice] = useState(null)
  const [endPrice, setEndPrice] = useState(null)
  const [timeLeft, setTimeLeft] = useState(30)
  const [wins, setWins] = useState(0)
  const [losses, setLosses] = useState(0)
  const [currentStreak, setCurrentStreak] = useState(0)
  const [bestStreak, setBestStreak] = useState(0)
  const [lastResult, setLastResult] = useState(null) // 'win' or 'lose'

  const intervalRef = useRef(null)
  const priceIntervalRef = useRef(null)

  // Fetch Bitcoin price from Pyth MCP
  const fetchPrice = async () => {
    const result = await pythMCP('get_symbols', { query: 'bitcoin', limit: 1 })
    if (result && result.length > 0) {
      const symbol = result[0].symbol
      const priceData = await pythMCP('get_historical_price', { 
        symbols: [symbol], 
        timestamp: Math.floor(Date.now() / 1000) 
      })
      if (priceData && priceData[symbol]) {
        const price = priceData[symbol].price
        setCurrentPrice(price)
        return price
      }
    }
    return null
  }

  // Update price every 2 seconds
  useEffect(() => {
    fetchPrice()
    priceIntervalRef.current = setInterval(fetchPrice, 2000)

    return () => {
      if (priceIntervalRef.current) clearInterval(priceIntervalRef.current)
    }
  }, [])

  const startGame = async (userPrediction) => {
    const price = await fetchPrice()
    if (!price) return

    setPrediction(userPrediction)
    setStartPrice(price)
    setGameState('active')
    setTimeLeft(30)
    setLastResult(null)

    // Start countdown
    intervalRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          endGame()
          return 0
        }
        return prev - 1
      })
    }, 1000)
  }

  const endGame = async () => {
    if (intervalRef.current) clearInterval(intervalRef.current)

    const finalPrice = await fetchPrice()
    if (!finalPrice || !startPrice) return

    setEndPrice(finalPrice)
    setGameState('finished')

    const priceWentUp = finalPrice > startPrice
    const playerWon = (prediction === 'up' && priceWentUp) || (prediction === 'down' && !priceWentUp)

    if (playerWon) {
      setWins(prev => prev + 1)
      setCurrentStreak(prev => {
        const newStreak = prev + 1
        if (newStreak > bestStreak) setBestStreak(newStreak)
        return newStreak
      })
      setLastResult('win')
    } else {
      setLosses(prev => prev + 1)
      setCurrentStreak(0)
      setLastResult('lose')
    }
  }

  const resetGame = () => {
    setGameState('waiting')
    setPrediction(null)
    setStartPrice(null)
    setEndPrice(null)
    setTimeLeft(30)
  }

  const formatPrice = (price) => {
    return price ? `$${price.toLocaleString(undefined, { maximumFractionDigits: 2 })}` : 'Loading...'
  }

  const getPriceChange = () => {
    if (!startPrice || !endPrice) return null
    const change = endPrice - startPrice
    const percentage = ((change / startPrice) * 100).toFixed(3)
    return {
      amount: change,
      percentage: percentage,
      isPositive: change > 0
    }
  }

  return (
    <div className="app">
      <div className="game-container">
        <h1>LOLOLOL</h1>
        <h2>Bitcoin 30-Second Price Prediction</h2>

        <div className="current-price">
          <div className="price-label">Current BTC Price</div>
          <div className="price-value">{formatPrice(currentPrice)}</div>
        </div>

        <div className="stats">
          <div className="stat">
            <div className="stat-number">{wins}</div>
            <div className="stat-label">Wins</div>
          </div>
          <div className="stat">
            <div className="stat-number">{losses}</div>
            <div className="stat-label">Losses</div>
          </div>
          <div className="stat">
            <div className="stat-number">{currentStreak}</div>
            <div className="stat-label">Current Streak</div>
          </div>
          <div className="stat">
            <div className="stat-number">{bestStreak}</div>
            <div className="stat-label">Best Streak</div>
          </div>
        </div>

        {gameState === 'waiting' && (
          <div className="game-area">
            <div className="prediction-question">
              Will Bitcoin go UP or DOWN in the next 30 seconds?
            </div>
            <div className="prediction-buttons">
              <button 
                className="prediction-btn up-btn" 
                onClick={() => startGame('up')}
                disabled={!currentPrice}
              >
                📈 UP
              </button>
              <button 
                className="prediction-btn down-btn" 
                onClick={() => startGame('down')}
                disabled={!currentPrice}
              >
                📉 DOWN
              </button>
            </div>
          </div>
        )}

        {gameState === 'active' && (
          <div className="game-area">
            <div className="game-active">
              <div className="prediction-display">
                You predicted: <span className={`prediction ${prediction}`}>{prediction.toUpperCase()}</span>
              </div>
              <div className="start-price">
                Starting price: {formatPrice(startPrice)}
              </div>
              <div className="countdown">
                <div className="countdown-number">{timeLeft}</div>
                <div className="countdown-label">seconds left</div>
              </div>
              <div className="live-price">
                Current: {formatPrice(currentPrice)}
              </div>
            </div>
          </div>
        )}

        {gameState === 'finished' && (
          <div className="game-area">
            <div className="result">
              <div className={`result-banner ${lastResult}`}>
                {lastResult === 'win' ? '🎉 YOU WON!' : '😞 YOU LOST!'}
              </div>

              <div className="price-comparison">
                <div className="price-item">
                  <div className="price-label">Start</div>
                  <div className="price-value">{formatPrice(startPrice)}</div>
                </div>
                <div className="arrow">→</div>
                <div className="price-item">
                  <div className="price-label">End</div>
                  <div className="price-value">{formatPrice(endPrice)}</div>
                </div>
              </div>

              {getPriceChange() && (
                <div className={`price-change ${getPriceChange().isPositive ? 'positive' : 'negative'}`}>
                  {getPriceChange().isPositive ? '+' : ''}${getPriceChange().amount.toFixed(2)} 
                  ({getPriceChange().isPositive ? '+' : ''}{getPriceChange().percentage}%)
                </div>
              )}

              <div className="your-prediction">
                Your prediction: <span className={`prediction ${prediction}`}>{prediction.toUpperCase()}</span>
              </div>

              <button className="play-again-btn" onClick={resetGame}>
                Play Again
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

export default App"}

